"use client"

import type { ReactNode } from "react"

import { Cheez } from "../cheez"
import type { CheezCharacter } from "../cheez-core/cheez-definition"
import type { CheezType } from "../mark-catalog"

export interface MarkedLabelProps {
  active: boolean
  animationKey?: number | string
  children: ReactNode
  character?: CheezCharacter
  className?: string
  color?: string
  mark?: CheezType
  thickness?: number
}

export function MarkedLabel({
  active,
  animationKey = 0,
  character = "rushed",
  children,
  className,
  color = "var(--cheez-accent, #ff4f2e)",
  mark = "underline",
  thickness = 1,
}: MarkedLabelProps) {
  return (
    <Cheez
      key={`${active ? "active" : "idle"}-${animationKey}`}
      className={className}
      type={mark}
      character={character}
      color={color}
      thickness={thickness}
      trigger={active ? "mount" : "manual"}
    >
      {children}
    </Cheez>
  )
}

export function joinCheezClassNames(
  ...classNames: Array<string | undefined>
) {
  return classNames.filter(Boolean).join(" ")
}

import type { CheezType } from "../mark-catalog"

export type MarkedFeedbackType =
  | "default"
  | "success"
  | "warning"
  | "error"
  | "info"
  | "loading"

export interface MarkedFeedbackAppearance {
  color: string
  mark: CheezType
}

export const MARKED_FEEDBACK_APPEARANCES: Record<
  MarkedFeedbackType,
  MarkedFeedbackAppearance
> = {
  default: { color: "#8f74ff", mark: "asterisk" },
  success: { color: "#b7ff3c", mark: "check" },
  warning: { color: "#ff4f2e", mark: "exclamation" },
  error: { color: "#ff5fa2", mark: "cross" },
  info: { color: "#35d9ff", mark: "spiral" },
  loading: { color: "#8f74ff", mark: "loop-arrow" },
}

export function getMarkedFeedbackType(type?: string): MarkedFeedbackType {
  if (type && type in MARKED_FEEDBACK_APPEARANCES) {
    return type as MarkedFeedbackType
  }

  return "default"
}

:where(.cheez-ui) {
  --cheez-accent: #ff4f2e;
  --cheez-background: #000;
  --cheez-foreground: #f4f0e6;
  --cheez-muted: rgba(244, 240, 230, 0.56);
  --cheez-line: rgba(244, 240, 230, 0.2);
  --cheez-surface: #0b0b0b;
  color: var(--cheez-foreground);
  font-family: Inter, ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}


/* marked table */
.cheez-table-shell {
  --cheez-table-row-color: var(--cheez-table-color);
  position: relative;
  min-width: 0;
  color: #f4f0e6;
  background: #000;
  isolation: isolate;
}

.cheez-table__frame {
  position: absolute !important;
  z-index: 0;
  inset: -1px;
  display: block !important;
  width: calc(100% + 2px);
  height: calc(100% + 2px);
  pointer-events: none;
}

.cheez-table__frame > svg {
  top: -0.75% !important;
  left: -0.5% !important;
  width: 101% !important;
  height: 101.5% !important;
}

.cheez-table__frame path,
.cheez-table__sort-mark path {
  vector-effect: non-scaling-stroke;
}

.cheez-table__frame path {
  stroke-width: var(--cheez-table-stroke) !important;
}

.cheez-table__scroll {
  position: relative;
  z-index: 1;
  width: 100%;
  overflow: auto;
  scrollbar-color: color-mix(in srgb, var(--cheez-table-color) 56%, transparent) #000;
  scrollbar-width: thin;
}

.cheez-table {
  width: 100%;
  min-width: 560px;
  border-collapse: separate;
  border-spacing: 0;
  color: inherit;
  font-size: 0.7rem;
  line-height: 1.45;
}

.cheez-table__caption {
  padding: 13px 14px;
  color: rgba(244, 240, 230, 0.42);
  font: 0.56rem/1.5 ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  text-align: left;
}

.cheez-table__caption[data-side="top"] {
  caption-side: top;
}

.cheez-table__caption[data-side="bottom"] {
  caption-side: bottom;
}

.cheez-table__head,
.cheez-table__cell {
  position: relative;
  min-width: 0;
  padding: 13px 14px;
  text-align: left;
  vertical-align: middle;
}

.cheez-table-shell[data-density="compact"] .cheez-table__head,
.cheez-table-shell[data-density="compact"] .cheez-table__cell {
  padding-block: 8px;
}

.cheez-table-shell[data-density="relaxed"] .cheez-table__head,
.cheez-table-shell[data-density="relaxed"] .cheez-table__cell {
  padding-block: 19px;
}

.cheez-table__head {
  color: rgba(244, 240, 230, 0.46);
  background: #000;
  font: 0.53rem/1.2 ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-weight: 560;
  letter-spacing: 0.075em;
  text-transform: uppercase;
}

.cheez-table-shell[data-sticky-header] .cheez-table__head {
  position: sticky;
  z-index: 3;
  top: 0;
}

.cheez-table__footer .cheez-table__cell {
  color: #f4f0e6;
  background: color-mix(in srgb, var(--cheez-table-color) 7%, #000);
  font-weight: 620;
}

.cheez-table__row {
  --cheez-table-active-color: var(
    --cheez-table-row-color,
    var(--cheez-table-color)
  );
  transition:
    color 140ms ease,
    opacity 140ms ease;
}

.cheez-table-shell[data-variant="ruled"] .cheez-table__head,
.cheez-table-shell[data-variant="framed"] .cheez-table__head {
  border-bottom: 0;
}

.cheez-table-shell[data-variant="ruled"] .cheez-table__head::after,
.cheez-table-shell[data-variant="framed"] .cheez-table__head::after {
  position: absolute;
  right: 7px;
  bottom: 0;
  left: 7px;
  height: 1px;
  background: color-mix(in srgb, var(--cheez-table-color) 52%, transparent);
  content: "";
  transform: rotate(-0.18deg);
  transform-origin: left center;
}

.cheez-table-shell[data-variant="ruled"] .cheez-table__head:nth-child(3n)::after,
.cheez-table-shell[data-variant="framed"] .cheez-table__head:nth-child(3n)::after {
  transform: rotate(0.24deg);
}

.cheez-table__body .cheez-table__row:nth-child(3n + 1) {
  --cheez-table-rule-tilt: -0.12deg;
}

.cheez-table__body .cheez-table__row:nth-child(3n + 2) {
  --cheez-table-rule-tilt: 0.16deg;
}

.cheez-table__body .cheez-table__row:nth-child(3n) {
  --cheez-table-rule-tilt: -0.06deg;
}

.cheez-table-shell[data-variant="ruled"] .cheez-table__body .cheez-table__row:not(:last-child) .cheez-table__cell::after,
.cheez-table-shell[data-variant="framed"] .cheez-table__body .cheez-table__row:not(:last-child) .cheez-table__cell::after {
  position: absolute;
  right: 6px;
  bottom: 0;
  left: 6px;
  height: 1px;
  background: rgba(244, 240, 230, 0.11);
  content: "";
  transform: rotate(var(--cheez-table-rule-tilt, 0deg));
  transform-origin: left center;
}

.cheez-table-shell[data-variant="framed"] .cheez-table__head + .cheez-table__head,
.cheez-table-shell[data-variant="framed"] .cheez-table__cell + .cheez-table__cell {
  border-left: 1px solid rgba(244, 240, 230, 0.07);
}

.cheez-table-shell[data-variant="quiet"] .cheez-table__header .cheez-table__row::after {
  position: absolute;
  right: 14px;
  bottom: 0;
  left: 14px;
  height: 1px;
  background: color-mix(in srgb, var(--cheez-table-color) 42%, transparent);
  content: "";
}

.cheez-table-shell[data-striped] .cheez-table__body .cheez-table__row:nth-child(even) .cheez-table__cell {
  background: rgba(244, 240, 230, 0.022);
}

.cheez-table__row[data-interactive] {
  cursor: pointer;
}

.cheez-table__row[data-interactive]:hover .cheez-table__cell,
.cheez-table__row:focus-within .cheez-table__cell {
  background: color-mix(
    in srgb,
    var(--cheez-table-active-color) 5%,
    #000
  );
}

.cheez-table__row[data-selected] .cheez-table__cell {
  background: color-mix(
    in srgb,
    var(--cheez-table-active-color) 10%,
    #000
  );
}

.cheez-table__row[data-selected] .cheez-table__cell:first-child {
  box-shadow: none;
}

.cheez-table__row[data-selected] .cheez-table__cell:first-child::before {
  position: absolute;
  top: 6px;
  bottom: 6px;
  left: 0;
  width: 4px;
  background: var(--cheez-table-active-color);
  clip-path: polygon(20% 0, 100% 3%, 74% 28%, 100% 52%, 68% 76%, 92% 100%, 0 97%, 22% 73%, 0 48%, 24% 22%);
  content: "";
}

.cheez-table__row[data-muted] {
  opacity: 0.42;
}

.cheez-table__head[data-align="center"],
.cheez-table__cell[data-align="center"] {
  text-align: center;
}

.cheez-table__head[data-align="end"],
.cheez-table__cell[data-align="end"],
.cheez-table__head[data-numeric],
.cheez-table__cell[data-numeric] {
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.cheez-table__cell[data-truncate] {
  max-width: 190px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.cheez-table__cell-mark {
  display: inline-block !important;
  max-width: 100%;
}

.cheez-table__cell-mark > span {
  min-width: 0;
}

.cheez-table__sort-button {
  display: inline-flex;
  align-items: center;
  justify-content: inherit;
  gap: 7px;
  max-width: 100%;
  padding: 0;
  border: 0;
  color: inherit;
  background: transparent;
  cursor: pointer;
  font: inherit;
  letter-spacing: inherit;
  text-align: inherit;
  text-transform: inherit;
}

.cheez-table__sort-button:hover,
.cheez-table__sort-button:focus-visible {
  color: #f4f0e6;
}

.cheez-table__sort-button:focus-visible {
  outline: 1px solid var(--cheez-table-color);
  outline-offset: 4px;
}

.cheez-table__sort-mark {
  display: inline-block !important;
  width: 13px;
  height: 13px;
  flex: 0 0 13px;
  opacity: 0.34;
  transition:
    opacity 140ms ease,
    transform 140ms ease;
}

.cheez-table__sort-mark > svg {
  top: -16% !important;
  left: -16% !important;
  width: 132% !important;
  height: 132% !important;
}

.cheez-table__sort-mark path {
  stroke-width: 1.8px !important;
}

.cheez-table__sort-button[data-direction="ascending"] .cheez-table__sort-mark,
.cheez-table__sort-button[data-direction="descending"] .cheez-table__sort-mark,
.cheez-table__sort-button:hover .cheez-table__sort-mark,
.cheez-table__sort-button:focus-visible .cheez-table__sort-mark {
  opacity: 1;
}

.cheez-table__empty-row,
.cheez-table__empty-row:hover {
  background: transparent;
}

.cheez-table__empty {
  height: 180px;
  padding: 32px;
  color: rgba(244, 240, 230, 0.42);
  text-align: center;
}

@media (prefers-reduced-motion: reduce) {
  .cheez-table__row,
  .cheez-table__sort-mark {
    transition: none;
  }
}


/* marked pagination */
.cheez-pagination {
  display: inline-flex;
  max-width: 100%;
  color: #f4f0e6;
}

.cheez-pagination[data-spread] {
  display: flex;
  width: 100%;
}

.cheez-pagination__list {
  display: flex;
  max-width: 100%;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 7px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.cheez-pagination[data-spread] .cheez-pagination__list {
  width: 100%;
}

.cheez-pagination[data-spread] .cheez-pagination__item:first-child {
  margin-right: auto;
}

.cheez-pagination[data-spread] .cheez-pagination__item:last-child {
  margin-left: auto;
}

.cheez-pagination__item {
  display: inline-flex;
  align-items: center;
}

.cheez-pagination__page,
.cheez-pagination__direction {
  -webkit-tap-highlight-color: transparent;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 0;
  color: rgba(244, 240, 230, 0.56);
  background: transparent;
  cursor: pointer;
  font: inherit;
  text-decoration: none;
}

.cheez-pagination__page {
  min-width: 36px;
  min-height: 36px;
  padding: 0;
  font-size: 0.72rem;
}

.cheez-pagination[data-size="small"] .cheez-pagination__page {
  min-width: 30px;
  min-height: 30px;
  font-size: 0.64rem;
}

.cheez-pagination[data-size="large"] .cheez-pagination__page {
  min-width: 44px;
  min-height: 44px;
  font-size: 0.82rem;
}

.cheez-pagination__page:hover,
.cheez-pagination__direction:hover,
.cheez-pagination__page:focus-visible,
.cheez-pagination__direction:focus-visible,
.cheez-pagination__page[data-current] {
  color: #f4f0e6;
}

.cheez-pagination__page:focus-visible,
.cheez-pagination__direction:focus-visible {
  outline: 1px solid var(--cheez-pagination-color);
  outline-offset: 3px;
}

.cheez-pagination__page[data-disabled],
.cheez-pagination__direction[data-disabled],
.cheez-pagination__page:disabled {
  pointer-events: none;
  cursor: not-allowed;
  opacity: 0.3;
}

.cheez-pagination__page-mark {
  display: inline-grid !important;
  min-width: 28px;
  min-height: 28px;
  place-items: center;
}

.cheez-pagination__page-mark > svg {
  top: -9% !important;
  left: -12% !important;
  width: 124% !important;
  height: 118% !important;
}

.cheez-pagination__page-mark path,
.cheez-pagination__arrow path {
  stroke-width: var(--cheez-pagination-stroke) !important;
  vector-effect: non-scaling-stroke;
}

.cheez-pagination__page-content {
  position: relative;
  z-index: 1;
  display: inline-grid;
  min-width: 20px;
  min-height: 20px;
  place-items: center;
  font-variant-numeric: tabular-nums;
}

.cheez-pagination__direction {
  gap: 8px;
  min-height: 36px;
  padding-inline: 6px;
  font-size: 0.68rem;
}

.cheez-pagination[data-size="small"] .cheez-pagination__direction {
  min-height: 30px;
  font-size: 0.62rem;
}

.cheez-pagination[data-size="large"] .cheez-pagination__direction {
  min-height: 44px;
  font-size: 0.78rem;
}

.cheez-pagination__arrow {
  display: inline-block !important;
  width: 27px;
  height: 18px;
  flex: 0 0 27px;
}

.cheez-pagination__arrow > svg {
  top: -22% !important;
  left: -10% !important;
  width: 120% !important;
  height: 144% !important;
}

.cheez-pagination[data-compact] .cheez-pagination__arrow-label {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

.cheez-pagination__ellipsis {
  position: relative;
  display: inline-grid;
  min-width: 28px;
  min-height: 36px;
  color: var(--cheez-pagination-color);
  font: 0.58rem/1 ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  letter-spacing: 0.14em;
  place-items: center;
}

.cheez-pagination__status {
  color: rgba(244, 240, 230, 0.48);
  font: 0.6rem/1.4 ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-variant-numeric: tabular-nums;
}

.cheez-pagination__sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

@media (max-width: 560px) {
  .cheez-pagination__list {
    gap: 3px;
  }

  .cheez-pagination:not([data-compact]) .cheez-pagination__arrow-label {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip: rect(0 0 0 0);
    white-space: nowrap;
  }
}


/* marked breadcrumb */
.cheez-breadcrumb {
  max-width: 100%;
  overflow-x: auto;
  color: #f4f0e6;
  scrollbar-width: none;
}

.cheez-breadcrumb::-webkit-scrollbar {
  display: none;
}

.cheez-breadcrumb__list {
  display: flex;
  width: max-content;
  min-width: 0;
  align-items: center;
  gap: 5px;
  margin: 0;
  padding: 4px;
  list-style: none;
  white-space: nowrap;
}

.cheez-breadcrumb[data-wrap] .cheez-breadcrumb__list {
  width: auto;
  flex-wrap: wrap;
  row-gap: 9px;
  white-space: normal;
}

.cheez-breadcrumb__item,
.cheez-breadcrumb__separator {
  display: inline-flex;
  min-width: 0;
  align-items: center;
}

.cheez-breadcrumb__link,
.cheez-breadcrumb__page,
.cheez-breadcrumb__ellipsis {
  -webkit-tap-highlight-color: transparent;
  display: inline-flex;
  min-width: 0;
  align-items: center;
  border: 0;
  color: rgba(244, 240, 230, 0.52);
  background: transparent;
  font: inherit;
  text-decoration: none;
}

.cheez-breadcrumb__link {
  cursor: pointer;
}

.cheez-breadcrumb__link:hover,
.cheez-breadcrumb__link:focus-visible,
.cheez-breadcrumb__page {
  color: #f4f0e6;
}

.cheez-breadcrumb__link:focus-visible,
.cheez-breadcrumb__ellipsis:focus-visible {
  outline: 1px solid var(--cheez-breadcrumb-color);
  outline-offset: 3px;
}

.cheez-breadcrumb__link-mark,
.cheez-breadcrumb__page-mark {
  display: inline-flex !important;
  min-height: 28px;
  align-items: center;
}

.cheez-breadcrumb__link-mark path,
.cheez-breadcrumb__page-mark path,
.cheez-breadcrumb__separator-mark path,
.cheez-breadcrumb__ellipsis-mark path {
  stroke-width: var(--cheez-breadcrumb-stroke) !important;
  vector-effect: non-scaling-stroke;
}

.cheez-breadcrumb__copy {
  position: relative;
  z-index: 1;
  display: block;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}

.cheez-breadcrumb__page .cheez-breadcrumb__copy {
  max-width: min(34vw, 260px);
  font-weight: 580;
}

.cheez-breadcrumb[data-size="small"] .cheez-breadcrumb__link,
.cheez-breadcrumb[data-size="small"] .cheez-breadcrumb__page {
  font-size: 0.58rem;
}

.cheez-breadcrumb[data-size="medium"] .cheez-breadcrumb__link,
.cheez-breadcrumb[data-size="medium"] .cheez-breadcrumb__page {
  font-size: 0.68rem;
}

.cheez-breadcrumb[data-size="large"] .cheez-breadcrumb__link,
.cheez-breadcrumb[data-size="large"] .cheez-breadcrumb__page {
  font-size: 0.8rem;
}

.cheez-breadcrumb[data-size="small"] .cheez-breadcrumb__link-mark,
.cheez-breadcrumb[data-size="small"] .cheez-breadcrumb__page-mark {
  min-height: 24px;
}

.cheez-breadcrumb[data-size="large"] .cheez-breadcrumb__link-mark,
.cheez-breadcrumb[data-size="large"] .cheez-breadcrumb__page-mark {
  min-height: 34px;
}

.cheez-breadcrumb__separator {
  color: var(--cheez-breadcrumb-color);
  opacity: 0.76;
}

.cheez-breadcrumb__separator-mark {
  display: inline-block !important;
  width: 19px;
  height: 19px;
}

.cheez-breadcrumb__separator-mark > svg {
  inset: 0 !important;
  width: 100% !important;
  height: 100% !important;
}

.cheez-breadcrumb__ellipsis {
  min-width: 32px;
  min-height: 30px;
  justify-content: center;
  padding: 0;
  cursor: pointer;
}

.cheez-breadcrumb__ellipsis-mark {
  display: inline-grid !important;
  min-width: 28px;
  min-height: 24px;
  color: rgba(244, 240, 230, 0.58);
  font: 0.56rem/1 ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  letter-spacing: 0.08em;
  place-items: center;
}

.cheez-breadcrumb__ellipsis-mark > svg {
  top: -14% !important;
  left: -10% !important;
  width: 120% !important;
  height: 128% !important;
}

.cheez-breadcrumb__ellipsis:disabled {
  cursor: not-allowed;
  opacity: 0.3;
}

@media (prefers-reduced-motion: reduce) {
  .cheez-breadcrumb__link,
  .cheez-breadcrumb__page,
  .cheez-breadcrumb__ellipsis {
    transition: none;
  }
}

.cheez-button,
.cheez-tabs__tab,
.cheez-dropdown__trigger,
.cheez-dropdown__item {
  -webkit-tap-highlight-color: transparent;
  font: inherit;
}

.cheez-button,
.cheez-dropdown__trigger {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 38px;
  border-radius: 0;
  color: var(--cheez-foreground);
  background: var(--cheez-background);
  cursor: pointer;
  font-size: 0.82rem;
  font-weight: 560;
}

.cheez-button {
  padding: 0;
  border: 1px solid transparent;
}

.cheez-button__mark {
  display: inline-flex !important;
  min-height: 36px;
  align-items: center;
  justify-content: center;
  padding-inline: 16px;
}

.cheez-dropdown__trigger {
  padding: 0 16px;
  border: 0;
}

.cheez-button[data-variant="solid"] {
  border-color: transparent;
  color: var(--cheez-background);
  background: transparent;
}

.cheez-button[data-variant="quiet"] {
  border-color: transparent;
}

.cheez-button[data-size="small"],
.cheez-dropdown__trigger[data-size="small"] {
  min-height: 32px;
  font-size: 0.72rem;
}

.cheez-button[data-size="small"] .cheez-button__mark {
  min-height: 30px;
  padding-inline: 12px;
