  justify-content: center;
  color: var(--cheez-foreground);
  font: 0.55rem ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  letter-spacing: 0.08em;
  line-height: 1;
  text-transform: uppercase;
  white-space: nowrap;
}

.cheez-separator__label-mark {
  padding: 5px 8px;
}

.cheez-separator__label-mark > svg {
  top: -8% !important;
  left: -5% !important;
  width: 110% !important;
  height: 116% !important;
}

.cheez-separator[data-variant="directional"] .cheez-separator__segment {
  min-width: 34px;
  min-height: 34px;
}

@media (max-width: 540px) {
  .cheez-separator[data-orientation="horizontal"][data-labelled] {
    gap: 8px;
  }

  .cheez-separator__label-mark {
    padding-inline: 6px;
  }
}


/* marked card */
.cheez-card {
  --cheez-card-pad: 24px;
  position: relative;
  display: grid;
  min-width: 0;
  gap: 18px;
  padding: var(--cheez-card-pad);
  color: var(--cheez-card-foreground);
  background: #000;
  isolation: isolate;
}

.cheez-card[data-size="compact"] {
  --cheez-card-pad: 17px;
  gap: 13px;
}

.cheez-card[data-size="large"] {
  --cheez-card-pad: 32px;
  gap: 24px;
}

.cheez-card[data-muted] {
  opacity: 0.48;
}

.cheez-card__frame,
.cheez-card__fill,
.cheez-card__quiet-mark,
.cheez-card__selection-frame {
  position: absolute !important;
  z-index: 0;
  inset: 0;
  display: block !important;
  width: 100%;
  height: 100%;
  pointer-events: none;
}

.cheez-card__frame {
  opacity: 0.9;
}

.cheez-card__frame > svg,
.cheez-card__selection-frame > svg {
  top: -1% !important;
  left: -0.75% !important;
  width: 101.5% !important;
  height: 102% !important;
}

.cheez-card__frame path,
.cheez-card__quiet-mark path,
.cheez-card__pin path,
.cheez-card__selection-frame path,
.cheez-card__selection-check path {
  stroke-width: var(--cheez-card-stroke) !important;
  vector-effect: non-scaling-stroke;
}

.cheez-card[data-interactive] .cheez-card__frame {
  transition: opacity 160ms ease;
}

.cheez-card[data-interactive]:hover .cheez-card__frame,
.cheez-card[data-interactive]:focus-within .cheez-card__frame {
  opacity: 1;
}

.cheez-card[data-interactive]:focus-within {
  outline: 1px solid color-mix(in srgb, var(--cheez-card-color) 58%, transparent);
  outline-offset: 4px;
}

.cheez-card[data-variant="filled"] {
  color: var(--cheez-card-foreground);
  background: var(--cheez-card-color);
  clip-path: polygon(0.5% 1%, 15% 0.2%, 34% 0.9%, 52% 0, 71% 0.8%, 86% 0.2%, 99.4% 1.2%, 100% 98.3%, 83% 99.1%, 65% 98.4%, 47% 100%, 29% 99%, 13% 99.6%, 0 98.7%);
}

.cheez-card__fill {
  opacity: 0.16;
}

.cheez-card__fill > svg {
  top: -4% !important;
  left: -3% !important;
  width: 106% !important;
  height: 108% !important;
}

.cheez-card__quiet-mark {
  top: auto !important;
  right: auto !important;
  bottom: 2px;
  left: var(--cheez-card-pad) !important;
  width: min(58%, 190px);
  height: 20px;
}

.cheez-card__quiet-mark > svg {
  top: 44% !important;
  left: 0 !important;
  width: 100% !important;
  height: 56% !important;
}

.cheez-card[data-variant="pinned"] {
  background: #000;
}

.cheez-card__pin {
  position: absolute !important;
  z-index: 4;
  top: -13px;
  right: 18px;
  display: block !important;
  width: 34px;
  height: 34px;
  pointer-events: none;
}

.cheez-card__pin > svg {
  top: -18% !important;
  left: -18% !important;
  width: 136% !important;
  height: 136% !important;
}

.cheez-card__selection-frame {
  z-index: 3;
}

.cheez-card__selection-check {
  position: absolute !important;
  z-index: 4;
  right: 12px;
  bottom: 10px;
  display: block !important;
  width: 24px;
  height: 24px;
  pointer-events: none;
}

.cheez-card__selection-check > svg {
  top: -18% !important;
  left: -18% !important;
  width: 136% !important;
  height: 136% !important;
}

.cheez-card__header,
.cheez-card__content,
.cheez-card__media,
.cheez-card__footer {
  position: relative;
  z-index: 2;
  min-width: 0;
}

.cheez-card__header {
  display: grid;
  gap: 8px;
}

.cheez-card__eyebrow {
  color: var(--cheez-card-color);
  font: 0.52rem ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  letter-spacing: 0.1em;
  line-height: 1.2;
  text-transform: uppercase;
}

.cheez-card[data-variant="filled"] .cheez-card__eyebrow {
  color: var(--cheez-card-foreground);
  opacity: 0.62;
}

.cheez-card__title {
  margin: 0;
  color: inherit;
  font-size: 1rem;
  font-weight: 610;
  line-height: 1.16;
  text-wrap: balance;
}

.cheez-card[data-size="compact"] .cheez-card__title {
  font-size: 0.78rem;
}

.cheez-card[data-size="large"] .cheez-card__title {
  font-size: 1.34rem;
}

.cheez-card__description {
  margin: 0;
  color: color-mix(in srgb, currentColor 52%, transparent);
  font-size: 0.62rem;
  line-height: 1.58;
}

.cheez-card__content {
  display: grid;
  gap: 12px;
  color: color-mix(in srgb, currentColor 74%, transparent);
  font-size: 0.62rem;
  line-height: 1.55;
}

.cheez-card__media {
  display: grid;
  min-height: 0;
  overflow: hidden;
  background: color-mix(in srgb, var(--cheez-card-color) 22%, #000);
  place-items: center;
}

.cheez-card__media[data-aspect="square"] {
  aspect-ratio: 1;
}

.cheez-card__media[data-aspect="video"] {
  aspect-ratio: 16 / 9;
}

.cheez-card__media[data-aspect="wide"] {
  aspect-ratio: 2 / 1;
}

.cheez-card[data-orientation="vertical"] .cheez-card__media[data-bleed="top"] {
  margin: calc(var(--cheez-card-pad) * -1) calc(var(--cheez-card-pad) * -1) 0;
}

.cheez-card__media[data-bleed="all"] {
  margin: calc(var(--cheez-card-pad) * -1);
}

.cheez-card__media[data-bleed="inline"] {
  margin-inline: calc(var(--cheez-card-pad) * -1);
}

.cheez-card__footer {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  margin-top: auto;
  color: color-mix(in srgb, currentColor 56%, transparent);
  font-size: 0.55rem;
}

.cheez-card__actions {
  display: inline-flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
}

.cheez-card[data-orientation="horizontal"] {
  grid-template-columns: minmax(150px, 0.78fr) minmax(0, 1fr);
  align-content: start;
}

.cheez-card[data-orientation="horizontal"]:not(:has(.cheez-card__media)) {
  grid-template-columns: minmax(0, 1fr);
}

.cheez-card[data-orientation="horizontal"] .cheez-card__media {
  grid-column: 1;
  grid-row: 1 / span 4;
  align-self: stretch;
}

.cheez-card[data-orientation="horizontal"] .cheez-card__header,
.cheez-card[data-orientation="horizontal"] .cheez-card__content,
.cheez-card[data-orientation="horizontal"] .cheez-card__footer {
  grid-column: 2;
}

.cheez-card[data-orientation="horizontal"]:not(:has(.cheez-card__media)) .cheez-card__header,
.cheez-card[data-orientation="horizontal"]:not(:has(.cheez-card__media)) .cheez-card__content,
.cheez-card[data-orientation="horizontal"]:not(:has(.cheez-card__media)) .cheez-card__footer {
  grid-column: 1;
}

.cheez-card[data-orientation="horizontal"] .cheez-card__media[data-bleed="inline"],
.cheez-card[data-orientation="horizontal"] .cheez-card__media[data-bleed="all"] {
  margin: calc(var(--cheez-card-pad) * -1) 0 calc(var(--cheez-card-pad) * -1) calc(var(--cheez-card-pad) * -1);
}

@media (max-width: 620px) {
  .cheez-card[data-orientation="horizontal"] {
    grid-template-columns: minmax(0, 1fr);
  }

  .cheez-card[data-orientation="horizontal"] .cheez-card__media,
  .cheez-card[data-orientation="horizontal"] .cheez-card__header,
  .cheez-card[data-orientation="horizontal"] .cheez-card__content,
  .cheez-card[data-orientation="horizontal"] .cheez-card__footer {
    grid-column: 1;
    grid-row: auto;
  }

  .cheez-card[data-orientation="horizontal"] .cheez-card__media[data-bleed="inline"],
  .cheez-card[data-orientation="horizontal"] .cheez-card__media[data-bleed="all"] {
    margin: calc(var(--cheez-card-pad) * -1) calc(var(--cheez-card-pad) * -1) 0;
  }

  .cheez-card__footer {
    align-items: flex-start;
    flex-direction: column;
  }

  .cheez-card__actions {
    justify-content: flex-start;
  }
}
